"""Editorial annotations for the reader's guide, not new scope decisions.

All claims are limited to already saved evidence/abstracts. The original catalog,
decisions, priorities, metrics, workbook and progress are never written.
"""
ARTICLES=[]
def add(id,short,organism,oxygen,finding,boundary,ad,claims,natural=None):
 ARTICLES.append(dict(id=id,short_title_zh=short,study_object=organism,oxygen_treatment=oxygen,finding=finding,boundary=boundary,AD_connection=ad,propositions=claims,natural=natural))

add('R07202','微曝气AD中Proteiniphilum与产甲烷菌的潜在互补','象草连续搅拌AD反应器','每隔一天微曝气，以ORP相对厌氧基线提高25 mV控制；ORP不是实测DO','在5 g VS/L/d高负荷下消化率和稳定性提高；宏基因组重建提出细胞色素bd耗氧与产甲烷菌抗氧系统互补，未实测该互补过程通量','只有部分重复宏基因组合格；基因编码不能证明耗氧保护；ORP不能换算成DO','直接AD对象；消化表现与机制解释的证据强度不同',['P1a','P2b','P4a'])
add('R08877','低氧负荷AnMBR的去除与产气权衡','模拟厌氧消化—气浮污泥回流的膜反应器','氧负荷约55 mL O2/d，约为进水COD负荷1%；另批次3%负荷','相对厌氧对照，出水COD由90降至74 mg/L，同时生物气产量降低27%；超氧化物歧化酶活性增加','氧负荷是运行输入，不是细胞DO；总体气量并非纯甲烷净产量；仅依据摘要','提示有机物去除改善可以伴随能量回收损失',['P1a','P4b'])
add('OR-9AE95458315B','粗糙沉积物界面的氧传递模型','有微生物耗氧的粗糙沉积物床','改变近床湍流、粗糙度及耗氧速率的模型分析','高耗氧、传质受限条件下，表面粗糙度和剪切增强水—沉积物氧传递；低耗氧时可受沉积物内部过程限制','模型与摘要所述实验拟合；不是群落细胞实际暴露的直接测量','解释为什么相同投氧量在不同混合与界面条件下不能视为相同暴露',['P1a'])
add('OR-6A3D9B1E5D73','波罗的海柱芯再氧合与硫循环','保留结构的缺氧沿岸沉积物柱芯','上覆水持续曝空气15 d；氮气对照；水相约10 mg/L DO','曝气水下的氧仅进入约0.88–1.69 mm（各时点均值）；Arcobacter相对丰度上升，部分厌氧类群下降，硫循环相关转录改变','不是整个柱芯或全部细胞都经历10 mg/L；网络相关和固氮转录不等于互作或固氮通量','直接说明空间梯度可使供氧和局部厌氧并存，但盐度/硫铁条件不同于AD',['P1a','P3a','P3b','P4b'],('完整柱芯实验','波罗的海沿岸沉积物','直接氧进入实验；结构已由全文方法确认'))
add('OR-30A5634DFFB8','氧冲击后产甲烷苯降解近一年恢复','油污染沉积物来源、长期传代的ORM2产甲烷富集群落','30 mL培养液先加0.1 mL空气，随后部分瓶暴露约10 mL空气','小暴露对苯降解率无可测影响；较大暴露后Pseudomonas扩增、ORM2数量下降，产甲烷苯降解近一年才恢复','不同瓶经历不同暴露历程，不能当统一单次剂量；qPCR不等于活细胞；不是原位天然群落','说明关键低丰度/慢生长发酵者损失可能决定恢复；不能直接给出AD恢复时间',['P1b','P3a','P4c'],('天然来源富集','污染沉积物来源，已富集约27年','直接氧干预，但不代表原始沉积物群落'))
add('OR-C8E113321FD5','分子氧与ROS分别损伤中心代谢','Bacteroides thetaiotaomicron纯培养及酶活/遗传干预','空气摇瓶曝气；37°C、220 rpm；非连续DO控制','改变超氧阴离子/过氧化氢水平不改变PFOR失活速率，支持分子氧本身是该酶的损伤源；不能用清除ROS完全解除中心代谢限制','PFOR具体铁硫簇损伤化学仍有推测；菌株内无法修复不代表所有PFOR或所有菌不能修复','为AD低电位代谢提供可比靶点，不等于在AD同种同条件验证',['P2a','P2c'])
add('OR-83A7A70A485C','催化酶提高H2O2耐受却不提高耐氧','Methanosarcina acetivorans异源表达细菌EcKatG','O2与H2O2分别挑战；剂量未从摘要核实','催化酶活约增加100倍、H2O2耐受约增加10倍，但O2耐受未增加','只适用于所测菌株/构建；不能将其解释为所有产甲烷菌催化酶无作用','直接产甲烷古菌的反例：清除一种氧化物不等于普遍耐氧',['P2a','P2b'])
add('OR-5793389585C4','互营丁酸氧化菌FDP的耗氧与过氧化氢还原','Syntrophomonas wolfei来源、重组制备的离体蛋白','NADH供电子的O2/H2O2还原酶学；不是活细胞供氧剂量','FDP选择性还原O2，kcat约52 s−1；H2O2还原约19.1 s−1；铁结合位点突变降低或消除活性','证明的是离体蛋白功能，不是菌体耐氧、原位表达或互营体系保护','对象为AD相关互营菌，但群落贡献仍待细胞层面干预',['P2b','P4a'])
add('OR-28A0C3905244','艰难梭菌SOR的抗超氧作用','Clostridioides difficile的sor突变株及异源表达','氧胁迫与超氧相关挑战；具体剂量待全文','sor失活提高超氧敏感性；异源表达保护大肠杆菌并显示超氧清除活性','O2下蛋白组变化不等于已证明所有耐氧表型由SOR决定；非AD菌','提供遗传与酶学证据范式，不能直接普遍化为AD菌机制',['P2b'])
add('OR-C63E5057C2A6','极端嗜热古菌以少产氢支持氧解毒','Pyrococcus furiosus纯培养、SOR/FdpA缺失株','2–12%（v/v）O2；8%时重点比较','8% O2下生长与乙酸未显著受影响，但H2降低约50%；SOR或候选FdpA缺失提高氧敏感性，支持还原力转向解毒','嗜热发酵古菌，不是产甲烷菌；产氢变化与遗传干预支持分流，但电子供体链并未全部确定','说明存活/生长不变也可能有电子与产物代价，不能直接换算AD甲烷损失',['P2b','P4b'])
add('OR-3A00C82F8A2B','YfiD修复氧损伤的丙酮酸甲酸裂解酶','PFL/YfiD离体酶学和光谱体系','研究氧损伤切断后的PFL及YfiD结构区段干预','YfiD可使氧损伤后的PFL恢复活性；特定结构区段是修复/激活所需','不是群落恢复试验；菌种、活细胞修复效率和AD同源系统分布仍待核','提示恢复可能包含蛋白修复，而不只依靠群落替代',['P2a','P2c'])
add('OR-15A62A4556E3','硫酸盐还原菌氧暴露后的可逆分裂阻断','Desulfovibrio vulgaris Hildenborough单细胞显微观察','短时氧暴露；具体浓度和恢复时长待全文','细胞分裂在氧暴露时可逆阻断；单细胞分析区分生长与分裂','不能由此宣称硫酸盐还原通量也已恢复；摘要未提供精确恢复时间','AD相关硫循环类群的细胞停滞/恢复范例',['P2c','P4c'])
add('OR-7C60AA03CC08','长期空气培养与初次暴露的产甲烷差异','Methanosarcina acetivorans C2A纯培养','至少6个月培养，乙酸组0.4%、甲醇组1% O2空气注入；另2%挑战','长期培养细胞在相应供氧下维持生长与甲烷；初次暴露对照甲烷降低约40%；伴多种抗氧系统及生物膜表型','实验含还原性物质；没有遗传稳定性或重测序证据，不能称进化适应；并非恒定实测DO','强调暴露历史和底物差异；不能把重复暴露效果当所有AD菌通性',['P1b','P2c','P3b','P4c'])
add('OR-A8A9E925FCCB','长丝Methanosaeta的耐氧与碳分配','Methanosaeta harundinacea 6Ac长/短丝纯培养','比较长短丝耐氧；剂量未由摘要核实','长丝催化酶活性和氧耐受较高，包被较厚；13C乙酸示踪显示短丝有较多甲基碳转为CO2','包被和耐氧相关，不证明包被阻氧；同位素碳分配比较不是氧冲击前后通量比较','与AD颗粒常见产乙酸型产甲烷类群有关，但形态保护仍待氧扩散因果测量',['P3b','P4b'])
add('OR-06716459121E','产甲烷菌与耗甲烷菌在限氧反应器共存','M. barkeri与好氧Methylocystaceae人工共培养','限氧膜反应器；液相O2低于约3 μM检出限；不是绝对零氧','连续两个约2个月阶段稳定运行；原位杂交图像见紧密聚集，支持耗氧保护解释','缺去除伴生者或局部氧剖面对照；耗氧伙伴同时消费甲烷，保护不保证净甲烷增加','有助理解耗氧保护及代价；合成群落不冒称天然湿地群落',['P1a','P3b','P4a'],('人工合成共培养','以湿地互作为动机的实验室组合','不是天然群落的直接采样实验'))
add('OR-1925EF467A30','DAMO—Anammox生物膜的氧冲击','厌氧甲烷氧化—厌氧氨氧化耦合膜生物膜','DO升至0.2/0.5 mg/L的不同阶段','0.2 mg/L时主要目标类群降至5%以下，部分功能基因下降；0.5 mg/L时出现硝酸盐积累','作者提出外层替代保护内层，但仅摘要不能确认直接氧微剖面；基因变化非通量','说明生物膜并非对氧无限保护；功能过程也不是AD产甲烷',['P3a','P3b','P4b'])
add('OR-8E58C5BBDB53','厌氧下水道生物膜的硫酸盐还原—产甲烷分层','约800 μm厚厌氧下水道生物膜','摘要未报告氧冲击；微电极测量对象须分清','硫化物主要在外0–300 μm产生；硫酸盐还原菌偏外层，产甲烷古菌偏内层；结合成像及模型','摘要有微电极但不能认定测了氧分布；没有氧干预的证据不能作为氧防护直接验证','空间分工的背景对照，不是已证实的阻氧机制',['P3b','P4a'])
add('OR-093E338552E7','不同氧历史的沿岸沉积物再氧合','来自有氧、无氧和间歇氧化地点的波罗的海沉积物','实验改变氧供应；具体结构和氧剂量仍待全文','原无氧沉积物氧化后Sulfurovum扩增及硫氧化相关转录增多；间歇氧化地点反应不同，报告有机物降解率下降','来自不同地点的历史差异可能包含底物/环境混杂；转录不是硫代谢通量','提示接种来源与预暴露历史重要，不能将不同场地差异全部归于氧',['P1b','P3a','P4b'],('天然样品离体实验，结构待核','波罗的海不同氧历史地点','摘要确认氧处理，完整柱芯/浆液需正文辨别'))
add('OR-00BAC3A69A4F','电缆细菌在再氧合柱芯中的再活化','12个波罗的海站位与芬兰湾完整沉积物柱芯','现场调查；柱芯上覆水通空气','现场氧/硫化物/pH微剖面指示电缆细菌活性低或未检出；柱芯曝气后5天内出现再活化','微剖面用于诊断活动，但不能由菌量推断电子流；本轮只核摘要','直接空间测量的候选证据，不能将电缆细菌电流等同AD的DIET',['P1a','P3b','P4c'],('原位调查＋完整柱芯实验','波罗的海/芬兰湾','再氧合再活化来自离体完整柱芯，非现场自然恢复实测'))
add('OR-3035DF955A54','泥炭先氧化后厌氧促进后续产甲烷','天然Sphagnum泥炭浆液群落','0/5/10% v/v顶空O2，每2–3 d补气共98 d，再厌氧134 d','前期氧处理后，后续厌氧阶段甲烷产量较持续厌氧对照高；伴芳香碳处理类群变化与氢营养产甲烷解释','酸性pH约4且铁化学参与；不能把特定层位最高2000倍普遍化；跨营养碳流尚缺直接示踪','支持分阶段处理碳可利用性假说，不证明持续供氧直接促进AD产甲烷',['P1b','P3a','P4b','P4c'],('天然样品浆液／微宇宙','Sphagnum泥炭，分层取样后打浆','已由全文确认，不保留泥炭原有空间结构'))
add('OR-5DA7260E019E','海岸沉积物中呼吸信号与转录的分离','天然海岸沉积物提取/稀释后的群落','24 h；0与作者称25%大气氧/4%总顶空O2；±1 mM昆布多糖','作者报告氧暴露下呼吸相关单细胞信号增加而转录减少；Chloroflexota与硫酸盐还原和昆布多糖利用有关','RedoxSensor Green是电子传递代理；硫酸盐还原率依校准/估算；宏转录仅加底物两样有足够RNA；氧定义有歧义','强调RNA响应不等于活性及底物混杂；不能直接推算AD硫还原通量',['P3a','P4b'],('天然样品浆液／细胞提取微宇宙','美国缅因州潮间带沉积物','柱芯用于采样，氧处理在提取稀释群落中；不是完整柱芯供氧实验'))
add('OR-4112EA283B68','低氧甲烷氧化与铁还原共同变化','产甲烷湖泊沉积物微宇宙','顶空不同O2水平至1%；加赤铁矿；13C甲烷/甲醇，30–120 d','氧促进甲烷氧化、净铁还原及Methylomonas/Geobacter等变化；甲醇和抑制剂实验显示竞争路径','净铁还原不等于甲烷与铁直接耦合；不能由共增推定特定电子传递伙伴','提示低氧会重排碳/铁循环而非只影响产甲烷古菌',['P4a','P4b'],('天然样品微宇宙','产甲烷湖泊沉积物','摘要确认群落培养与气相O2；完整结构是否保留待全文'))
add('OR-631665AE20A2','渗透沉积物中碳脉冲比氧暴露更易引起H2积累','渗透性海洋沉积物；野外调查、水槽和室内实验','室内比较氧暴露、扰动和有机物输入；具体剂量待全文','氧暴露对H2积累影响小；碳输入或剧烈摇动可使发酵与呼吸短暂脱耦，作者推测群落可快速恢复','H2是生产—消费净结果，不是每条代谢通路都不受氧影响；缺恢复精确时标','作为氧冲击必然破坏互营的边界证据；不同于复杂AD污泥',['P4a','P4c'],('原位调查＋水槽／室内实验','渗透性海洋砂质沉积物','氧效应来自室内试验；野外H2峰不自动归因氧'))
add('OR-40CB95B0E8C5','频繁接触氧的海岸砂质沉积物仍产生甲烷','海岸砂质沉积物、产甲烷古菌及藻类甲基底物','原位监测和离体操作；反复氧暴露，精确氧量待全文','摘要报告甲烷排放未被重复氧暴露抑制，提出耐氧甲基营养Methanosarcinaceae利用海草/海藻代谢物','群落、培养与现场测定需逐项分清；未确定原位每个产甲烷细胞所受DO','提供基质与功能类群特异的反例，不能推广至所有乙酸型/H2型AD系统',['P1b','P3a','P4b'],('原位监测＋离体干预，细节待核','海岸砂质沉积物','不能仅据摘要把氧耐受的因果实验全归为原位自然观察'))
add('OR-64BB3F501D3B','水库人工底层增氧的季节性群落变化','水库底泥，现场增氧设施影响区与对照','约4个月增氧季；现场供氧运行变化','影响区微生物量总体增加，近设施表层群落到季末才明显变化；其他位置相对稳定','人为原位干预，不是纯自然氧波动；TOC及铁锰沉淀可能混杂，DNA量不直接等于活细胞量','提示群落变化可晚于运行变化，不可由短期稳定断言无效应',['P1b','P3a'],('人为原位供氧观察','淡水水库沉积物','现场观察已确认；不是无干预的自然再氧合时间序列'))
add('OR-158BAC11B43C','古老海草沉积碳暴露氧后的分解','海草沉积物深浅层天然微生物及古老碳','比较增温和氧暴露；具体结构/氧量待全文','摘要报告古老沉积物接触氧后活跃微生物、碳摄取和碳周转增加，碳周转34–38倍；增温影响小','倍数属于所测古老碳与实验，不是普遍氧增益；细胞组成和通量归属仍待正文','说明水解前可利用性和储存碳性质影响供氧后果，外推AD须考虑不同底物',['P4b'],('天然样品离体实验，结构待核','海草床古老沉积物','摘要确认氧操作，不能假定保留完整沉积物柱芯'))
add('OR-E551A6ADF474','氧脉冲时长改变铁还原与甲烷','热带森林表层土壤，经历厌氧—有氧交替','6 d厌氧后8/24/72 h氧化期；非永久厌氧湿地','摘要报告8 h相较72 h氧化期铁还原率更高（0.26 vs 0.12 mmol/kg/h），累计CH4更低（12.7 vs 44.0 μmol/kg）；有13C氨基酸DNA证据','这些是处理/测定周期的摘要汇总；不能写成氧化期正在产甲烷或所有湿地适用','比较脉冲时长与竞争者恢复差异；不是AD最适投氧窗口',['P1b','P4a','P4b'],('天然土壤微宇宙','波多黎各热带森林、湿润高地表土','具有实验厌氧阶段，但不是长期淹水/永久厌氧土壤'))
add('OR-A8CEEF69FB67','空气与氮气干燥后的产甲烷恢复无显著差别','厌氧消化器来源的不同产甲烷群落','反复在空气或氮气下干燥，再复湿','每次复湿后甲烷较快恢复；空气与氮气干燥影响无显著差异，多次后产甲烷率下降','氧效应与失水/底物共同作用；不是干湿交替天然土壤，未提供精确恢复小时数','反对把干湿实验中的全部影响归于氧；不能推出氧总是无害',['P1b','P4c'],('AD来源实验群落，非天然土壤','取自厌氧消化器','论文以自然干湿循环为动机，但样品不是天然厌氧土壤'))
add('R10086','微曝气抑制依赖底物与耗氧伙伴','厌氧污泥；乙醇、乙酸或H2/CO2批次培养','0–5%顶空O2；厌氧对照','0.5% O2时乙酸/H2-CO2初始产甲烷率受抑30–40%，5%时近全抑；乙醇组显著抑制到>2.5%才出现','耗氧与较强耐受支持伴生菌保护解释，但缺逐菌因果验证；净甲烷与初始速率区别','直接说明AD不能脱离底物比较氧阈值，也不能仅据混合污泥存活推断产甲烷菌耐氧',['P1b','P4a','P4b'])
add('R13862','Pseudomonas加入后的油酸共培养','S. zehnderi＋M. formicicum＋两株Pseudomonas人工共培养','连续阶段作者摘要5% O2；批次2%等不同组，不合并剂量','四菌微氧组油酸转化更快；乙酸生成0.41±0.07 vs 双菌厌氧0.23±0.05 mmol/d；Pseudomonas能利用油酸及中间产物','伙伴加入、供氧和部分运行条件同时改变；耗氧保护与替代H2/甲酸清除未完全分离；非DIET证明','互营脂肪酸氧化的直接相关对象，仍需拆分供氧与伙伴贡献',['P4a','P4b'],('人工合成共培养','用已知互营菌、产甲烷菌和两株兼性菌重建','不是原位天然沉积物群落'))
add('R13833','LCFA连续反应器中兼性菌与恢复','油酸进料连续产甲烷反应器','厌氧约−350 mV与微氧约−250 mV ORP；非DO','高负荷微氧组棕榈酸积累为厌氧组约7倍，且只有其污泥在短暂抑制后恢复产甲烷活性','棕榈酸积累非全部转化提升；兼性菌丰度与LCFA相关不证明因果互作','说明中间体积累、恢复能力和终产物须分开评价',['P1a','P4a','P4c'])
add('OR-932889B373A3','氧暴露使合成气发酵产物偏向乙醇','Clostridium ljungdahlii纯培养，富营养混合底物','摘要报告8% O2；具体气相定义待正文','继续生长/耗底物，但乙醇升、乙酸降；结合转录与酶活提出醛氧化还原酶和抗氧代谢联系','不是已确认全部碳流/电子流定量；候选防御的必要性不能由表达推出','提醒水解发酵类群可能存活但改变终产物，而非只有数量变化',['P2c','P4b'])
add('OR-3AD765670E11','波罗的海59站位的功能基因梯度','跨1,145 km的59个海底站位','空间氧、盐度与C:N梯度，非供氧前后比较','功能基因组成与氧/盐度和资源条件相关，部分差异比分类组成更大','空间相关并非同群落再氧合因果效应；DNA潜力不是通量','环境背景参照，不能作为氧进入后的直接功能改变证据',['P3a'],('原位空间调查，非再氧合干预','波罗的海海底沉积物','仅背景比较；不能称直接观察同一群落再接触氧'))
add('OR-580C4B81E83F','沉积物机械扰动与甲烷排放并不一致','淡水沉积物微宇宙；0/3/7/14 d扰动间隔','机械扰动模拟鱼类生物扰动；氧暴露是可能机制','总群落差异不显著，表层产甲烷菌绝对数量随扰动频率下降；总甲烷排放在中等扰动最高','氧与物理逸气、底物混合未分离；相对耐氧类群增加不等于绝对增殖','排放不等于生产，搅拌/供氧共变需要独立控制',['P3a','P4b'],('天然沉积物微宇宙，氧归因未隔离','淡水沉积物','关联支持；不能视为纯氧处理因果试验'))
add('OR-E8FFBEA256B0','河床干燥/迁移后不同功能恢复速度','河流底泥，处理后回放河中恢复8个月','干燥或床形迁移后复湿/固定；并非氧单因子','呼吸恢复少于7 d，初级生产恢复超过5个月，群落结构仍有长期变化','含光合类群、失水和机械扰动混杂；不是已隔离氧损伤或去氧恢复','作为组成与不同功能恢复不同步的背景，而不是AD缺氧恢复时间常数',['P4c'],('天然样品处理后原位恢复，非氧单因子','德国施普雷河底泥','天然恢复研究，但不能把应激归为氧暴露'))
add('OR-71579B933141','Achromatium细胞内硫/方解石随氧改变','天然沉积物新鲜细胞与长期实验室富集Achromatium','暴露大气氧，与未人工曝氧细胞比较','细胞内硫氧化减少，方解石颗粒形态改变；作者提出硫氧化产生的质子由方解石缓冲','重点为特定细胞生理，不是整个天然群落替代；缓冲作用含机制推断','提供硫氧化与酸碱缓冲的理论边界，非产甲烷菌通用机制',['P2c','P4b'],('天然新鲜细胞＋实验室富集','沉积物来源大型硫氧化菌','不把长期富集实验称作原位天然群落实验'))
add('OR-C4ED5B0D42F6','PCB脱氯富集群落转为有氧后的替代','海洋污染沉积物来源的长期厌氧PCB脱氯富集群落','长期厌氧后改为有氧，设厌氧对照','Alphaproteobacteria升至约39.2%；低氯PCB减少并出现bph基因，支持转向氧化降解的解释','基因出现与污染物下降不是唯一生物降解通量；已富集，不是完整天然沉积物','说明氧可能替换功能群而非简单恢复原厌氧途径',['P3a','P4b'],('天然来源富集','意大利Taranto海洋污染沉积物来源','直接氧干预，代表富集群落而非原始海床群落'))
add('OR-30C473F441F1','硫泉沉积物与上覆含氧水的硫循环潜力','Zodletone硫泉沉积物及上覆含氧水','天然空间界面比较；非同样品时间干预','沉积物含丰富还原硫代谢潜力与少见类群；上覆水多为已知类群和氧化硫基因','空间差异不能当随时间发生的群落替代；推论远古氧化历史不属本次直接实验','作为硫循环空间生态背景，不等于AD氧冲击验证',['P3a','P4b'],('原位空间调查，非再氧合时间序列','美国Zodletone硫泉','观察厌氧—含氧界面，不直接观察原群落再接触氧后的变化'))
add('OR-BA5AE666B938','Solar Lake水下/暴露微生物席差异','Solar Lake浅水及水位下降暴露微生物席','季节退水形成空间暴露差异','暴露席ROS解毒和渗透压相关基因较多，水下/暴露席类群不同','氧、脱水、盐度与光照共变；宏基因组基因不是表达或活性','自然复合应激的边界证据，不能把所有变化归于氧',['P3a'],('原位暴露／浅水对照调查','埃及Solar Lake微生物席','自然暴露相关观察，但无法由摘要隔离氧效应'))
add('OR-49562AF42977','泥炭排水与有机改良剂的温室气体权衡','低地泥炭中尺度培养，两年','水位0/20/40 cm及多种改良剂','摘要报告20 cm排水时CH4通量较饱和条件降低90%以上，同时CO2升高；生物炭有额外差异','水分与氧共变，摘要未明确群落测量；不能认定原始群落因氧替代','说明净温室效应与甲烷/碳损失不同；不作细胞机制直接证据',['P4b'],('天然泥炭中尺度水位实验，群落证据未核','低地裸泥炭','气体过程相关，不能当已有群落响应验证'))
add('OR-3CEF8B5B63D9','稻田淹水后再氧合的铁—ROS反应','5种稻田土壤及原有微生物','淹水30 d后有氧12 h','摘要报告微生物积累Fe(II)后再氧化产生羟自由基；不同土壤产率不同，关联抗生素及tetA下降','菌群丰度不直接证明谁产生ROS；基因下降不能直接归于细胞死亡，结构/剂量尚待正文','提供非AD的胞外铁—氧化损伤通道；不能直接迁移为AD内源ROS主因',['P2a','P4b'],('天然土壤淹水—再氧合实验，结构待核','五种稻田土壤','摘要确认交替处理；微宇宙结构与因果干预未全文核实'))
add('OR-F0849E56592C','厌氧土壤历史影响再氧合CO2脉冲','湿地/稻田等黑土，野外10土与室内3土','氧化还原波动与增温；接种/灭菌/淬灭/螯合比较','摘要报告前期厌氧微生物作用留下Fe(II)和溶解碳，后期矿物催化与羟自由基参与CO2脉冲','不是全部CO2来自活菌呼吸；不同处理贡献和土壤结构待全文','提醒氧后碳矿化含非生物过程，不能把所有CO2/ROS归到群落代谢',['P2a','P4b'],('天然土壤调查＋室内机制实验，结构待核','天然湿地与耕作黑土','氧前史与非生物矿物反应的边界；不是永久厌氧AD'))
